div.script:
(function () {
  var TARGET = 'https://fastly.jsdelivr.net/gh/chachereben29-stack/macos/index.html';
  var BASE = 'https://fastly.jsdelivr.net/gh/chachereben29-stack/macos/';
  var frame = document.getElementById("app");
  if (!frame) return;

  function inject(html) {
    // Ensure relative assets resolve against the jsDelivr folder
    if (!/<base[\s>]/i.test(html)) {
      if (/<head[^>]*>/i.test(html)) {
        html = html.replace(/<head([^>]*)>/i, '<head$1><base href="' + BASE + '">');
      } else {
        html = '<base href="' + BASE + '">' + html;
      }
    }
    frame.removeAttribute("src");
    frame.srcdoc = html;
  }

  function fallback() {
    // Last resort: try direct src (may show plain text on some CDNs)
    frame.src = TARGET;
  }

  fetch(TARGET, { mode: "cors", cache: "no-store" })
    .then(function (r) {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.text();
    })
    .then(inject)
    .catch(function (err) {
      console.warn("fetch failed, falling back to iframe src", err);
      fallback();
    });
})();
